const i = $input.first().json;
let d = String(i.phone || '').replace(/[^0-9]/g, '');
if (d.startsWith('00')) d = d.slice(2);
if (d.length === 8) d = '973' + d;
const mode = String(i.mode || 'text');
const p = { To: 'whatsapp:+' + d, MessagingServiceSid: 'MG4cf17c1ce3add815f97ff92153a3033d' };
if (mode === 'booking_confirm') { p.ContentSid = 'HX55091e8f14f238dd8ba066cadf962fac'; p.ContentVariables = JSON.stringify({ '1': String(i.name || 'عميلنا العزيز'), '2': String(i.ref || ''), '3': String(i.details || '') }); }
else p.Body = String(i.text || '');
const bad = d.length < 10 || (mode !== 'booking_confirm' && !p.Body) || (mode === 'booking_confirm' && !i.ref);
if (bad) p.To = '';
const form = Object.keys(p).map(function (k) { return encodeURIComponent(k) + '=' + encodeURIComponent(p[k]); }).join('&');
return [{ json: { bad, phone: '+' + d, mode, staff: String(i.staff || ''), preview: p.Body || ('booking_confirm ' + (i.ref || '')), form } }];

const r = $input.first().json;
const ok = /^2/.test(String(r.status)) && !r.error;
return [{ json: { ok, phone: r.phone, message_sid: r.sid, error: ok ? '' : (r.error || ('HTTP ' + r.status)), hint: ok ? 'Sent' : 'If the error mentions 24 hours / outside window, free text cannot be sent until the customer messages us first; use the booking_confirm template or ask the owner.' } }];

